"use client";

import { createContext, useContext, useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./avatar.css";

export type AvatarProps = Omit<ComponentProps<"span">, "children"> & {
  name: string;
  src?: string;
  alt?: string;
  /** "square" for a company, workspace or integration: a coloured mark instead of a person's orb or photo. */
  shape?: "circle" | "square";
  /** Shown as a shape at the corner: filled, half, dash or ring. */
  presence?: "online" | "away" | "busy" | "offline";
};

/** Resolves a person's photo from their name when an Avatar has no `src`: your user directory, or sample faces in a demo.
    Return undefined for anyone without one and they keep their orb. */
export const AvatarPhotos = createContext<((name: string) => string | undefined) | null>(null);

/** The same name always gets the same orb (six glass orbs; the first follows the accent). */
export function avatarTone(name: string) {
  let hash = 7;
  for (const char of name.trim().toLowerCase()) hash = (hash * 31 + char.codePointAt(0)!) >>> 0;
  return hash % 6;
}

function AvatarContent({ src, initials }: { src?: string; initials: string }) {
  const [failed, setFailed] = useState(false);
  return (
    <>
      <span aria-hidden="true">{initials}</span>
      {src && !failed && (
        <img
          src={src}
          alt=""
          aria-hidden="true"
          width={32}
          height={32}
          decoding="async"
          className="absolute inset-0 size-full object-cover"
          ref={(image) => {
            // A cached or pre-hydration failure may precede the error listener.
            if (image?.complete && image.naturalWidth === 0) setFailed(true);
          }}
          onError={() => setFailed(true)}
        />
      )}
    </>
  );
}

export function Avatar({
  name,
  src,
  alt = name,
  shape = "circle",
  presence,
  className,
  ...props
}: AvatarProps) {
  const resolve = useContext(AvatarPhotos);
  const photo = src ?? (shape === "circle" ? resolve?.(name) : undefined);
  const words = name.trim().normalize("NFC").split(/\s+/u);
  const initials =
    (Array.from(words[0] ?? "")[0] ?? "?") +
    (words.length > 1 ? (Array.from(words[words.length - 1]!)[0] ?? "") : "");

  return (
    <span
      data-slot="avatar"
      data-tone={avatarTone(name)}
      data-shape={shape === "square" ? "square" : undefined}
      className={cn(
        "relative inline-flex size-8 shrink-0 items-center justify-center text-xs font-semibold",
        shape === "square" ? "rounded-[8px]" : "rounded-full",
        className,
      )}
      {...props}
      role={alt ? "img" : undefined}
      aria-label={alt || undefined}
      aria-hidden={!alt || undefined}
    >
      <AvatarContent
        key={photo ?? ""}
        src={photo}
        initials={initials.toUpperCase()}
      />
      {presence && <span data-slot="avatar-presence" data-presence={presence} aria-hidden="true" />}
    </span>
  );
}

import type { ComponentProps, CSSProperties } from "react";
import { cn } from "./lib/cn";

const variants = {
  neutral: "bg-muted text-muted-foreground",
  info: "bg-brand-subtle text-[color-mix(in_srgb,var(--accent-text)_82%,var(--foreground))]",
  success: "bg-success-subtle text-success",
  warning: "bg-warning-subtle text-warning",
  error: "bg-destructive-subtle text-destructive",
};

/* Status survives without colour: each variant has its own shape. */
const shapes = {
  neutral: <path d="M2 5h6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />,
  info: <circle cx="5" cy="5" r="3.6" fill="none" stroke="currentColor" strokeWidth="1.6" />,
  success: <circle cx="5" cy="5" r="4" fill="currentColor" />,
  warning: (
    <>
      <path d="M5 1a4 4 0 0 1 0 8z" fill="currentColor" />
      <circle cx="5" cy="5" r="4" fill="none" stroke="currentColor" strokeWidth="1.6" />
    </>
  ),
  error: <path d="M2 2l6 6M8 2 2 8" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />,
};

/* Categorical hues for labels that name a kind, not a status (a deal stage, a team, a type): OKLCH hue angles.
   Lightness and chroma come per theme from tokens.css (--tone-*), so the text holds 4.5:1 on its wash in both. */
export const toneHues = { blue: 255, violet: 295, rose: 2, orange: 50, amber: 82, green: 150, teal: 195, slate: 260 } as const;
export type BadgeTone = keyof typeof toneHues;

export type BadgeProps = ComponentProps<"span"> & {
  variant?: keyof typeof variants;
  /** A categorical hue with a dot, for kinds rather than statuses. Overrides the variant's colour. */
  tone?: BadgeTone;
  /** The status shape before the word. On for status variants, off for neutral labels and counts. */
  shape?: boolean;
};

export function Badge({
  className,
  variant = "neutral",
  tone,
  shape = variant !== "neutral" && !tone,
  children,
  style,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant}
      data-tone={tone}
      className={cn(
        "inline-flex h-[22px] shrink-0 items-center gap-1.5 whitespace-nowrap rounded-full px-2 text-xs leading-4 font-medium [&_svg]:size-3",
        (shape || tone) && "pl-[7px]",
        tone
          ? "bg-[oklch(var(--tone-bg-l)_var(--tone-bg-c)_var(--tone-h))] text-[oklch(var(--tone-fg-l)_var(--tone-fg-c)_var(--tone-h))]"
          : variants[variant],
        className,
      )}
      style={tone ? ({ "--tone-h": toneHues[tone], ...style } as CSSProperties) : style}
      {...props}
    >
      {tone && <span data-slot="badge-dot" aria-hidden="true" className="size-1.5 shrink-0 rounded-full bg-current" />}
      {shape && (
        <svg data-slot="badge-shape" viewBox="0 0 10 10" aria-hidden="true" className="!size-2.5">
          {shapes[variant]}
        </svg>
      )}
      {children}
    </span>
  );
}

"use client";
import { useMemo, useState } from "react";
import { Badge, type BadgeTone } from "./badge";
import { Avatar } from "./avatar";
import { cn } from "./lib/cn";
import "./shared/table-skeleton.css";
import "./shared/prompt-suggestion.css";
import "./blog-grid.css";

export type BlogPost = {
  id: string;
  title: string;
  excerpt: string;
  href: string;
  /** ISO date. */
  date: string;
  readTime?: string;
  category?: string;
  author?: { name: string; avatar?: string };
  image?: { src: string; alt: string };
};

const dateFormat = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });

function PostCard({ post, featured, tone }: { post: BlogPost; featured?: boolean; tone?: BadgeTone }) {
  return (
    <article data-slot="blog-card" data-featured={featured || undefined} className="group relative grid content-start gap-3">
      {post.image && (
        <div className={cn("overflow-hidden rounded-overlay bg-muted", featured ? "aspect-[16/9]" : "aspect-[3/2]")}>
          <img src={post.image.src} alt={post.image.alt} loading="lazy" draggable={false} data-slot="blog-image" className="size-full object-cover" />
        </div>
      )}
      <div className="grid gap-2">
        <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-muted-foreground">
          {post.category && <Badge tone={tone}>{post.category}</Badge>}
          <time dateTime={post.date}>{dateFormat.format(new Date(post.date))}</time>
          {post.readTime && <span aria-hidden="true">·</span>}
          {post.readTime && <span>{post.readTime}</span>}
        </div>
        <h3 className={cn("font-semibold tracking-tight", featured ? "text-xl sm:text-2xl" : "text-base")}>
          <a href={post.href} data-slot="blog-link">
            {post.title}
          </a>
        </h3>
        <p className={cn("text-muted-foreground", featured ? "line-clamp-3 text-base" : "line-clamp-3 text-sm")}>{post.excerpt}</p>
        {post.author && (
          <p className="mt-1 flex items-center gap-2 text-xs text-muted-foreground">
            <Avatar name={post.author.name} src={post.author.avatar} className="size-6 text-[10px]" alt="" />
            {post.author.name}
          </p>
        )}
      </div>
    </article>
  );
}

/** Articles in a grid, the newest one larger, with an optional category filter. */
export function BlogGrid({
  posts,
  title = "From the blog",
  description,
  featured = true,
  tones,
  loading,
  className,
}: {
  posts: readonly BlogPost[];
  title?: string;
  description?: string;
  /** Show the first post larger when there are at least three. */
  featured?: boolean;
  /** One hue per category, e.g. { Engineering: "blue" }. Categories without one stay neutral. */
  tones?: Partial<Record<string, BadgeTone>>;
  loading?: boolean;
  className?: string;
}) {
  const [category, setCategory] = useState<string | null>(null);
  const categories = useMemo(() => [...new Set(posts.map((p) => p.category).filter((c): c is string => !!c))], [posts]);
  const shown = category ? posts.filter((p) => p.category === category) : posts;
  const lead = featured && shown.length >= 3 ? shown[0] : null;
  const rest = lead ? shown.slice(1) : shown;
  return (
    <section data-slot="blog-grid" aria-label={title} className={cn("@container mx-auto grid w-full max-w-6xl gap-8 px-4 py-12 sm:px-6", className)}>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div className="grid gap-1.5">
          <h2 className="text-2xl font-semibold tracking-tight">{title}</h2>
          {description && <p className="text-sm text-muted-foreground">{description}</p>}
        </div>
        {categories.length > 1 && (
          <div role="group" aria-label="Filter by category" className="flex flex-wrap gap-1.5">
            {[null, ...categories].map((c) => (
              <button key={c ?? "all"} type="button" data-slot="prompt-suggestion" aria-pressed={category === c} onClick={() => setCategory(c)}>
                {c ?? "All"}
              </button>
            ))}
          </div>
        )}
      </div>
      {loading ? (
        <div aria-busy="true" className="grid gap-8 @xl:grid-cols-2 @4xl:grid-cols-3">
          {Array.from({ length: 3 }, (_, i) => (
            <div key={i} className="grid gap-3" aria-hidden="true">
              <span data-slot="table-skeleton" style={{ height: "10rem" }} />
              <span data-slot="table-skeleton" style={{ width: "40%" }} />
              <span data-slot="table-skeleton" />
            </div>
          ))}
        </div>
      ) : shown.length ? (
        <div className="grid gap-x-6 gap-y-10 @xl:grid-cols-2 @4xl:grid-cols-3">
          {lead && (
            <div className="@xl:col-span-2">
              <PostCard post={lead} featured tone={lead.category ? tones?.[lead.category] : undefined} />
            </div>
          )}
          {rest.map((post) => (
            <PostCard key={post.id} post={post} tone={post.category ? tones?.[post.category] : undefined} />
          ))}
        </div>
      ) : (
        <p className="rounded-overlay border border-dashed border-border p-8 text-center text-sm text-muted-foreground">No posts in this category yet.</p>
      )}
      <p className="sr-only" role="status">
        {category ? `${shown.length} ${shown.length === 1 ? "post" : "posts"} in ${category}` : ""}
      </p>
    </section>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* avatar.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Avatars: a light glass orb, two soft hues with a specular highlight and a deeper lower edge. Six tones, assigned per
     person, so a row of people reads as a calm spectrum; dark initials read on every tone at 9:1 or better. */
  [data-slot="avatar"] {
    --av-a: #9ec5ff;
    --av-b: #c4b2ff;
    color: #161616;
    background:
      radial-gradient(circle at 30% 24%, rgb(255 255 255 / 80%), rgb(255 255 255 / 0%) 36%),
      radial-gradient(circle at 76% 84%, color-mix(in oklab, var(--av-b) 78%, #3b2a6b), transparent 58%),
      linear-gradient(140deg, var(--av-a) 12%, var(--av-b) 88%);
    box-shadow: inset 0 0 0 1px rgb(255 255 255 / 34%), inset 0 -4px 8px rgb(0 0 0 / 8%);
  }
  [data-slot="avatar"] > span:first-child {
    position: relative;
    text-shadow: 0 1px 0 rgb(255 255 255 / 35%);
  }
  [data-slot="avatar"] img {
    border-radius: inherit;
  }
  [data-slot="avatar"][data-tone="1"] { --av-a: #a3f0c8; --av-b: #7fd3e6; }
  [data-slot="avatar"][data-tone="2"] { --av-a: #c9adff; --av-b: #ffb2d8; }
  [data-slot="avatar"][data-tone="3"] { --av-a: #ffd6a0; --av-b: #ffab86; }
  [data-slot="avatar"][data-tone="4"] { --av-a: #ffb4a6; --av-b: #ff9ec6; }
  [data-slot="avatar"][data-tone="5"] { --av-a: #b8c6ff; --av-b: #9fe1f0; }
  /* Company marks (shape="square"): a solid hue from the name with white initials, 4.7:1 or better on every hue. */
  [data-slot="avatar"][data-shape="square"] {
    --mark-h: 255;
    color: #ffffff;
    background: oklch(0.52 0.15 var(--mark-h));
    box-shadow: inset 0 0 0 1px rgb(255 255 255 / 12%);
  }
  [data-slot="avatar"][data-shape="square"] > span:first-child { text-shadow: none; }
  [data-slot="avatar"][data-shape="square"][data-tone="1"] { --mark-h: 295; }
  [data-slot="avatar"][data-shape="square"][data-tone="2"] { --mark-h: 2; }
  [data-slot="avatar"][data-shape="square"][data-tone="3"] { --mark-h: 50; }
  [data-slot="avatar"][data-shape="square"][data-tone="4"] { --mark-h: 150; }
  [data-slot="avatar"][data-shape="square"][data-tone="5"] { --mark-h: 195; }
  [data-slot="avatar-presence"] {
    position: absolute;
    right: -3px;
    bottom: -3px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    box-shadow: 0 0 0 2px var(--background);
  }
  [data-slot="avatar-presence"][data-presence="online"] { background: var(--success); }
  [data-slot="avatar-presence"][data-presence="away"] { background: linear-gradient(90deg, var(--warning) 50%, var(--background) 50%); box-shadow: 0 0 0 2px var(--background), inset 0 0 0 1.5px var(--warning); }
  [data-slot="avatar-presence"][data-presence="busy"] { background: radial-gradient(var(--background) 0 0) center / 5px 1.5px no-repeat, var(--danger); }
  [data-slot="avatar-presence"][data-presence="offline"] { background: var(--background); box-shadow: 0 0 0 2px var(--background), inset 0 0 0 1.5px var(--muted-foreground); }
}

/* Shared by blog-grid.tsx, chat-thread.tsx, link-unfurl.tsx, multi-chain-swap.tsx, sortable-table.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="table-skeleton"] {
    display: block;
    height: 0.75rem;
    border-radius: 4px;
    background: var(--muted);
    animation: caliper-skeleton-pulse 1.4s ease-in-out infinite;
  }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="table-skeleton"] {
      animation: none;
    }
  }
}

/* Shared by blog-grid.tsx, changelog-feed.tsx, prediction-market.tsx, prompt-input.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="prompt-suggestion"] {
    padding: 0.375rem 0.75rem;
    border: 1px solid var(--border);
    border-radius: 999px;
    font-size: 0.8125rem;
    color: var(--muted-foreground);
    outline: none;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }
  [data-slot="prompt-suggestion"]:hover:not(:disabled) {
    background: var(--muted);
    color: var(--foreground);
  }
  [data-slot="prompt-suggestion"]:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}

/* blog-grid.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="blog-link"] {
    color: inherit;
    text-decoration: none;
    outline: none;
  }
  [data-slot="blog-link"]::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: var(--radius-overlay, 12px);
  }
  [data-slot="blog-link"]:focus-visible::after {
    outline: 2px solid var(--ring);
    outline-offset: 4px;
  }
  [data-slot="blog-card"]:hover [data-slot="blog-link"] {
    text-decoration: underline;
    text-underline-offset: 4px;
  }
  [data-slot="blog-image"] {
    transition: transform var(--duration-travel) var(--ease-showcase);
  }
  [data-slot="blog-card"]:hover [data-slot="blog-image"] {
    transform: scale(1.03);
  }
  [data-slot="blog-grid"] [data-slot="prompt-suggestion"][aria-pressed="true"] {
    background: var(--accent);
    border-color: var(--accent);
    color: var(--accent-foreground);
  }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="blog-image"] {
      transition: none;
    }
  }
}
